import os, ctypes
import numpy as np
import ot
from scipy.optimize import linear_sum_assignment

_lib = None
try:
    _lib = ctypes.CDLL(os.path.join(os.path.dirname(os.path.abspath(__file__)), "build", "liblap.so"))
    _lib.solve_lap.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_int, ctypes.c_double, ctypes.c_int, ctypes.c_void_p]
    _lib.solve_lap.restype = ctypes.c_int
except Exception:
    _lib = None


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n, m = M.shape
        if n == m and n > 1 and a.shape == (n,) and b.shape == (n,):
            w = a[0]
            if w > 0 and (a == w).all() and (b == w).all():
                # uniform equal weights: an optimal vertex of the transport polytope
                # is a scaled permutation matrix -> linear assignment problem.
                colof = np.empty(n, dtype=np.int32)
                ok = False
                if _lib is not None:
                    ok = _lib.solve_lap(M.ctypes.data, n, 32, 1e-6, 4, colof.ctypes.data) == 0
                if not ok:
                    _, colof = linear_sum_assignment(M)
                G = np.zeros((n, n))
                G[np.arange(n), colof] = w
                return {"transport_plan": G}
        G = ot.lp.emd(a, b, M, check_marginals=False)
        return {"transport_plan": G}

