/* sparse shortest augmenting path assignment with dense optimality check */
typedef struct {double d; int j;} HE;
static void hpush(HE*h,int*n,double d,int j){int i=(*n)++;while(i>0){int p=(i-1)/2;if(h[p].d<=d)break;h[i]=h[p];i=p;}h[i].d=d;h[i].j=j;}
static HE hpop(HE*h,int*n){HE top=h[0];HE x=h[--(*n)];int i=0,m=*n;for(;;){int c=2*i+1;if(c>=m)break;if(c+1<m&&h[c+1].d<h[c].d)c++;if(h[c].d>=x.d)break;h[i]=h[c];i=c;}h[i]=x;return top;}

static int cmpd_n; static const double* cmpd_row;
/* select k smallest indices from row (length n) into out */
static void topk(const double*row,int n,int k,int*idx,int*out){
  for(int i=0;i<n;i++)idx[i]=i;
  int lo=0,hi=n-1,kk=k;
  while(lo<hi){
    double piv=row[idx[(lo+hi)/2]];int a=lo,b=hi;
    while(a<=b){while(row[idx[a]]<piv)a++;while(row[idx[b]]>piv)b--;if(a<=b){int t=idx[a];idx[a]=idx[b];idx[b]=t;a++;b--;}}
    if(kk-1<=b)hi=b;else if(kk-1>=a)lo=a;else break;
  }
  memcpy(out,idx,k*sizeof(int));
}

/* returns 0 ok, -1 failure (no perfect matching in sparse graph) ; colof output */
