  free(cc);
  int *rowof=malloc(n*sizeof(int));double*v=malloc(n*sizeof(double)),*cm=malloc(n*sizeof(double));
  double*d=malloc(n*sizeof(double));int*pred=malloc(n*sizeof(int));int*state=malloc(n*sizeof(int));int*fin=malloc(n*sizeof(int));
  HE*heap=malloc(sizeof(HE)*((size_t)n*n+n));
  int*start=NULL,*adj=NULL;double*ac=NULL;
  int ret=0;
  for(int iter=0;iter<20;iter++){
    /* build CSR */
    free(start);free(adj);free(ac);
    start=malloc((n+1)*sizeof(int));start[0]=0;
    for(int i=0;i<n;i++){int c=0;const unsigned char*f=flag+(size_t)i*n;for(int j=0;j<n;j++)c+=f[j];start[i+1]=start[i]+c;}
    int E=start[n];adj=malloc(E*sizeof(int));ac=malloc(E*sizeof(double));
    for(int i=0;i<n;i++){int p=start[i];const unsigned char*f=flag+(size_t)i*n;for(int j=0;j<n;j++)if(f[j]){adj[p]=j;ac[p]=C[(size_t)i*n+j];p++;}}
    /* column reduction init */
    for(int j=0;j<n;j++){v[j]=INFINITY;rowof[j]=-1;pred[j]=-1;}
    for(int i=0;i<n;i++)colof[i]=-1;
    for(int i=0;i<n;i++)for(int p=start[i];p<start[i+1];p++){int j=adj[p];if(ac[p]<v[j]){v[j]=ac[p];pred[j]=i;}}
    for(int j=0;j<n;j++){if(pred[j]<0){ret=-1;goto done;}int i=pred[j];if(colof[i]<0){colof[i]=j;rowof[j]=i;cm[i]=ac[0]*0+C[(size_t)i*n+j];}}
    for(int j=0;j<n;j++)state[j]=0;
    for(int s=0;s<n;s++){
      if(colof[s]>=0)continue;
      int hn=0,nf=0;
      for(int p=start[s];p<start[s+1];p++){int j=adj[p];double dd=ac[p]-v[j];if(state[j]==0||dd<d[j]){d[j]=dd;pred[j]=s;state[j]=1;fin[nf++]=j;state[j]=1;hpush(heap,&hn,dd,j);}}
      /* fin used as touched list first; we track touched separately */
      int ntouch=nf; int*touch=fin; /* reuse: touched cols listed in fin[0..ntouch) */
      int *done_=idx; int nd=0; int endj=-1;double delta=0;
