          if(state[jj]==0){state[jj]=1;d[jj]=dd;pred[jj]=i;touch[ntouch++]=jj;hpush(heap,&hn,dd,jj);}
          else if(dd<d[jj]){d[jj]=dd;pred[jj]=i;hpush(heap,&hn,dd,jj);}}
      }
      if(endj<0){ret=-1;goto done;}
      for(int t=0;t<nd;t++){int j=done_[t];v[j]+=d[j]-delta;}
      /* augment */
      int j=endj;
      for(;;){int i=pred[j];int nx=colof[i];colof[i]=j;rowof[j]=i;cm[i]=C[(size_t)i*n+j];if(i==s)break;j=nx;}
      for(int t=0;t<ntouch;t++)state[touch[t]]=0;
    }
    /* verify on dense matrix: c_ij - u_i - v_j >= -eps */
    int viol=0;
    for(int i=0;i<n;i++){double ui=cm[i]-v[colof[i]];const double*r=C+(size_t)i*n;unsigned char*f=flag+(size_t)i*n;
      for(int j=0;j<n;j++){if(r[j]-ui-v[j]<-1e-12){if(!f[j]){f[j]=1;viol++;}}}}
    if(!viol){ret=0;goto done;}
  }
  ret=-1;
done:
  free(idx);free(cand);free(colbuf);free(flag);free(deg);free(rowof);free(v);free(cm);free(d);free(pred);free(state);free(fin);free(heap);free(start);free(adj);free(ac);
  return ret;
}
