#include <stdlib.h>
#include <string.h>
#include <math.h>
/* dense LAPJV (Jonker-Volgenant) */
int lapjv(const double*C,int n,int*x /*colof*/){
  int *y=malloc(n*sizeof(int)),*freer=malloc(n*sizeof(int)),*collist=malloc(n*sizeof(int)),*matches=calloc(n,sizeof(int)),*pred=malloc(n*sizeof(int));
  double *v=malloc(n*sizeof(double)),*d=malloc(n*sizeof(double));
  for(int i=0;i<n;i++)x[i]=-1;
  /* column reduction */
  for(int j=n-1;j>=0;j--){double m=C[j];int im=0;for(int i=1;i<n;i++){double c=C[(size_t)i*n+j];if(c<m){m=c;im=i;}}
    v[j]=m;if(++matches[im]==1){x[im]=j;y[j]=im;}else{y[j]=-1;} }
  /* fix: if a row got multiple columns, only first assigned via x; set y properly */
  for(int j=0;j<n;j++)y[j]=-1;
  for(int i=0;i<n;i++)if(x[i]>=0)y[x[i]]=i;
  int nfree=0;
  for(int i=0;i<n;i++){
    if(matches[i]==0)freer[nfree++]=i;
    else if(matches[i]==1){int j1=x[i];double m=INFINITY;const double*r=C+(size_t)i*n;
      for(int j=0;j<n;j++)if(j!=j1){double t=r[j]-v[j];if(t<m)m=t;}
      v[j1]-=m;}
  }
  /* rows with matches>1 that weren't assigned: x[i] is set, others' columns had y=-1 -> those columns free; rows without x are free */
  /* recompute free rows: rows with x[i]<0 */
  nfree=0;for(int i=0;i<n;i++)if(x[i]<0)freer[nfree++]=i;
  /* augmenting row reduction, 2 passes */
  for(int loop=0;loop<2;loop++){
    int k=0,prv=nfree;nfree=0;
    while(k<prv){
      int i=freer[k++];const double*r=C+(size_t)i*n;
      double u1=r[0]-v[0],u2=INFINITY;int j1=0,j2=-1;
      for(int j=1;j<n;j++){double h=r[j]-v[j];if(h<u2){if(h>=u1){u2=h;j2=j;}else{u2=u1;u1=h;j2=j1;j1=j;}}}
      int i0=y[j1];
      if(u1<u2){v[j1]-=u2-u1;}
      else if(i0>=0){j1=j2;i0=y[j2];}
      if(i0>=0){ if(u1<u2) freer[--k]=i0; else freer[nfree++]=i0; }
      x[i]=j1;y[j1]=i;
      if(i0>=0)x[i0]=-1;
    }
  }
  /* augmentation */
  for(int f=0;f<nfree;f++){
    int fr=freer[f];const double*r=C+(size_t)fr*n;
    for(int j=0;j<n;j++){d[j]=r[j]-v[j];pred[j]=fr;collist[j]=j;}
    int low=0,up=0,last=0,endofpath=-1;double mn=0;
    for(;;){
      if(up==low){
        last=low-1;
        mn=d[collist[up++]];
        for(int k=up;k<n;k++){int j=collist[k];double h=d[j];if(h<=mn){if(h<mn){up=low;mn=h;}collist[k]=collist[up];collist[up++]=j;}}
        for(int k=low;k<up;k++)if(y[collist[k]]<0){endofpath=collist[k];goto aug;}
      }
      int j1=collist[low++];int i=y[j1];const double*ri=C+(size_t)i*n;
      double u1=ri[j1]-v[j1]-mn;
      for(int k=up;k<n;k++){int j=collist[k];double h=ri[j]-v[j]-u1;
        if(h<d[j]){pred[j]=i;if(h==mn){if(y[j]<0){endofpath=j;goto aug;}collist[k]=collist[up];collist[up++]=j;}d[j]=h;}}
    }
  aug:
    for(int k=0;k<=last;k++){int j1=collist[k];v[j1]+=d[j1]-mn;}
    for(;;){int i=pred[endofpath];y[endofpath]=i;int j1=endofpath;endofpath=x[i];x[i]=j1;if(i==fr)break;}
  }
  free(y);free(freer);free(collist);free(matches);free(pred);free(v);free(d);
  return 0;
}
