/* auction (min-cost): returns bids or -1 */
static long auction(int n,const int*RJ,const double*RC,const int*deg,int stride,double*v,int*colof,int*rowof,int*freeq,double eps,double efin,double fac,long maxb){
  long nb=0;
  for(;;){
    for(int i=0;i<n;i++)colof[i]=-1;
    for(int j=0;j<n;j++)rowof[j]=-1;
    int qh=0,qn=0,cnt=n;for(int i=0;i<n;i++)freeq[i]=i;
    while(cnt>0){
      int i=freeq[qh];qh=(qh+1==n)?0:qh+1;cnt--;
