      double w1=INFINITY,w2=INFINITY;int j1=-1;
      for(int p=0;p<dg;p++){double w=rc[p]-v[rj[p]];if(w<w2){if(w<w1){w2=w1;w1=w;j1=rj[p];}else w2=w;}}
