static int phase(P*p,int*colof,int*rowof,int*freeq,double eps,long maxb,double*buf){
  int n=p->n;double*v=p->v;
  for(int i=0;i<n;i++){colof[i]=-1;freeq[i]=i;}for(int j=0;j<n;j++)rowof[j]=-1;
  int cnt=n,qh=0,qn=0;
  while(cnt>0){
    int i=freeq[qh];qh=(qh+1==n)?0:qh+1;cnt--;
  again:;
    const int*rj=p->J[i];const double*rc=p->W[i];int dg=p->deg[i];
    double w1=INFINITY,w2=INFINITY;int j1=-1;
    for(int q=0;q<dg;q++){double w=rc[q]-v[rj[q]];if(w<w2){if(w<w1){w2=w1;w1=w;j1=rj[q];}else w2=w;}}
    double ex=p->ex[i];
    if(w1>ex){buildrow(p,i,dg*2,buf);next++;goto again;}
    if(w2>ex)w2=ex;
    if(w2==INFINITY)w2=w1;
    v[j1]-=(w2-w1)+eps;nbids++;
    int o=rowof[j1];rowof[j1]=i;colof[i]=j1;
    if(o>=0){colof[o]=-1;freeq[qn]=o;qn=(qn+1==n)?0:qn+1;cnt++;}
    if(nbids>maxb)return -1;
  }
  return 0;}

int solve_lap(const double*C,int n,int k,double es,double ef,double fac,int bidcap,int nthreads,int*colof){
  int dbg=getenv("LAPDBG")!=NULL;double t0=now(),t1=0,t2=0,t3=0;
  if(n<4)return -10;
  NTH=nthreads<1?1:(nthreads>16?16:nthreads);
  P p;p.n=n;p.C=C;p.v=malloc(n*sizeof(double));p.J=calloc(n,sizeof(int*));p.W=calloc(n,sizeof(double*));p.deg=calloc(n,sizeof(int));p.cap=calloc(n,sizeof(int));p.ex=malloc(n*sizeof(double));
  double*bufs=malloc((size_t)NTH*2*n*sizeof(double)),*cms=malloc((size_t)NTH*n*sizeof(double));
  int*rowof=malloc(n*sizeof(int)),*freeq=malloc(n*sizeof(int)),*inq=calloc(n,sizeof(int)),*cnt=calloc(n,sizeof(int));
  double*v=p.v;int ret=0;nbids=0;next=0;
  prun(&p,0,0,bufs,cms);
  for(int j=0;j<n;j++){double m=cms[j];for(int t=1;t<NTH;t++){double x=cms[(size_t)t*n+j];m=x<m?x:m;}v[j]=m;}
  double cmax=-INFINITY,cmin=INFINITY;for(int j=0;j<n;j++)cmin=v[j]<cmin?v[j]:cmin;
  for(int i=0;i<n;i+=37){const double*r=C+(size_t)i*n;for(int j=0;j<n;j++)cmax=r[j]>cmax?r[j]:cmax;}
  double range=cmax-cmin;if(!(range>0)||!isfinite(range)){ret=-5;goto done;}
  for(int j=0;j<n;j++)if(!isfinite(v[j])){ret=-5;goto done;}
  prun(&p,1,k,bufs,cms);
  t1=now();
  double eps=range*es,efin=range*ef;
  for(int attempt=0;attempt<3;attempt++){
    for(;;){if(phase(&p,colof,rowof,freeq,eps,(long)bidcap*n,bufs)<0){ret=-2;goto done;}
      if(eps<=efin)break;eps*=fac;if(eps<efin)eps=efin;}
    t2=now();
    /* exact potentials: v_j <= v_a + c_ij - c_ia over graph edges; SPFA */
    for(int j=0;j<n;j++)rowof[j]=-1;for(int i=0;i<n;i++)rowof[colof[i]]=i;
    int qh=0,qn=0,qs=n;for(int a=0;a<n;a++){freeq[a]=a;inq[a]=1;cnt[a]=0;}
    int neg=0;
    while(qs>0){int a=freeq[qh];qh=(qh+1==n)?0:qh+1;qs--;inq[a]=0;
      int i=rowof[a];const int*rj=p.J[i];const double*rc=p.W[i];double base=v[a]-C[(size_t)i*n+a];
      for(int q=0;q<p.deg[i];q++){int j=rj[q];if(j==a)continue;double t=base+rc[q];if(v[j]>t){v[j]=t;
        if(!inq[j]){inq[j]=1;freeq[qn]=j;qn=(qn+1==n)?0:qn+1;qs++;if(++cnt[j]>n+1){neg=1;break;}}}}
      if(neg)break;}
    int bad=neg;
    if(!neg){double tol=1e-12*range;
      for(int i=0;i<n&&!bad;i++){int a=colof[i];double ui=C[(size_t)i*n+a]-v[a];
        if(ui>p.ex[i]+tol){bad=1;break;}
        const int*rj=p.J[i];const double*rc=p.W[i];
        for(int q=0;q<p.deg[i];q++)if(rc[q]-v[rj[q]]<ui-tol){bad=1;break;}}}
    t3=now();
    if(dbg)fprintf(stderr,"attempt %d neg %d bad %d ",attempt,neg,bad);
    if(!bad){ret=0;goto done;}
    /* rows whose u exceeds ex need extension: handled lazily in next phase; continue with smaller eps */
    eps=efin;efin*=1e-3;
    ret=-3;
  }
done:
  if(dbg)fprintf(stderr,"ret %d init %.3f auc %.3f (bids %ld ext %ld) cert %.3f total %.3f\n",ret,(t1-t0)*1e3,(t2-t1)*1e3,nbids,next,(t3-t2)*1e3,(now()-t0)*1e3);
  for(int i=0;i<n;i++){free(p.J[i]);free(p.W[i]);}
  free(p.J);free(p.W);free(p.deg);free(p.cap);free(p.ex);free(p.v);free(bufs);free(cms);free(rowof);free(freeq);free(inq);free(cnt);
  return ret;
}
